import json, collections, os
E='/app/export/'
def load(t):
    return [json.loads(l) for l in open(E+t+'.ndjson')]
res={t:load(t) for t in ['Patient','EpisodeOfCare','Condition','Observation','Specimen','Basic','MedicationAdministration','MedicationDispense','DocumentReference','AllergyIntolerance','Task','Task']}
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
def et(r): return ext(r,'event-time') or r.get('created') or ''
def subj(r):
    for k in ['subject','patient','for']:
        if k in r and isinstance(r[k],dict) and 'reference' in r[k]:
            return r[k]['reference'].split('/')[-1]
    return None
pats={p['id']:p for p in res['Patient']}
by=collections.defaultdict(list)
noSubj=[]
for t,rs in res.items():
    for r in rs:
        s=subj(r)
        if s: by[s].append(r)
        else: noSubj.append(r)
# accession index
acc_basic=collections.defaultdict(list)
for r in res['Basic']:
    acc_basic[ext(r,'accession')].append(r)
spec_by_id={s['id']:s for s in res['Specimen']}
obs_by_spec=collections.defaultdict(list)
for o in res['Observation']:
    if 'specimen' in o: obs_by_spec[o['specimen']['reference'].split('/')[-1]].append(o)

def fmt(r):
    t=r['resourceType']; i=r['id']; e=et(r)
    if t=='Patient':
        return f"PATIENT {i} {r['name'][0]['text']} dob={r['birthDate']} sex={r['gender']} mrn={r['identifier'][0]['value']}"
    if t=='EpisodeOfCare':
        return f"EPISODE {i} start={r['period']['start']} type={r['type'][0]['text']} status={r['status']}"
    if t=='Condition':
        return f"[{e}] CONDITION {i} '{r['code']['text']}' recorder={r.get('recorder',{}).get('display')} recorded={r.get('recordedDate')}"
    if t=='Observation':
        sp=r.get('specimen',{}).get('reference','').split('/')[-1]
        acc=r.get('identifier',[{}])[0].get('value')
        notes=' | '.join(n['text'] for n in r.get('note',[]))
        return (f"[{e}] OBS {i} '{r['code']['text']}' coll={r.get('effectiveDateTime')} issued={r.get('issued')} status={r['status']} "
                f"val={r.get('valueString')!r} acc={acc} spec={sp}"+(f" NOTE: {notes}" if notes else ''))
    if t=='Specimen':
        return (f"[{e}] SPECIMEN {i} acc={r.get('accessionIdentifier',{}).get('value')} coll={r.get('collection',{}).get('collectedDateTime')} "
                f"collector={r.get('collection',{}).get('collector',{}).get('display')} label_name={ext(r,'label-name')} label_mrn={ext(r,'label-mrn')} label_dob={ext(r,'label-dob')} type={r.get('type',{}).get('text')}")
    if t=='MedicationAdministration':
        notes=' | '.join(n['text'] for n in r.get('note',[]))
        return (f"[{e}] MEDADMIN {i} {r['medicationCodeableConcept']['text']} dose={r.get('dosage',{}).get('text')} status={r['status']} "
                f"when={r.get('effectiveDateTime')} by={[p['actor']['display'] for p in r.get('performer',[])]}"+(f" NOTE: {notes}" if notes else ''))
    if t=='MedicationDispense':
        notes=' | '.join(n['text'] for n in r.get('note',[]))
        return (f"[{e}] MEDDISP {i} {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} "
                f"handed={r.get('whenHandedOver')} sig={[d['text'] for d in r.get('dosageInstruction',[])]}"+(f" NOTE: {notes}" if notes else ''))
    if t=='DocumentReference':
        return (f"[{e}] DOC {i} type='{r['type']['text']}' author={[a['display'] for a in r.get('author',[])]} role={ext(r,'author-role')} date={r.get('date')} docStatus={r.get('docStatus')}\n    TEXT: "+r.get('description','').replace('\n','\n    '))
    if t=='AllergyIntolerance':
        return f"[{e}] ALLERGY {i} {r['code']['text']} reaction={[m['text'] for rr in r.get('reaction',[]) for m in rr['manifestation']]} recorded={r.get('recordedDate')}"
    if t=='Task':
        if r['status']=='requested':
            return f"[{r.get('authoredOn')}] REQUEST {i} issue={r['code']['coding'][0]['code']} focus={r['focus']['reference']} desc={r['description']}"
        return f"TASK-ITEM {i} {json.dumps(r)[:400]}"
    return json.dumps(r)[:300]

def basic_fmt(r):
    return (f"[{et(r)}] ACCESSION {r['id']} acc={ext(r,'accession')} name={ext(r,'patient-name')} mrn={ext(r,'patient-mrn')} dob={ext(r,'patient-dob')} received={ext(r,'received')} author={r.get('author',{}).get('display')}")

pdata=json.load(open('/app/patients.json'))
out=open('/app/work/charts.txt','w')
for entry in pdata['patients']:
    pid=entry['patient']['id']
    recs=by[pid]
    out.write('='*100+'\n')
    out.write(fmt(pats[pid])+'\n')
    accs=set()
    for r in recs:
        if r['resourceType']=='Specimen': accs.add(r.get('accessionIdentifier',{}).get('value'))
        if r['resourceType']=='Observation':
            for idd in r.get('identifier',[]): accs.add(idd.get('value'))
    shown=[r for r in recs if r['resourceType']!='Patient']
    extra=[b for a in accs for b in acc_basic.get(a,[])]
    allr=sorted(shown+extra, key=lambda r:(et(r) or r.get('authoredOn','')))
    for r in allr:
        out.write((basic_fmt(r) if r['resourceType']=='Basic' else fmt(r))+'\n')
out.close()
print('ok')
EOF
cd /app && python3 work/render.py && wc -l work/charts.txt

