    out.write("  OTHEROBS: "+str(others)+"\n")
    bad=[l for l in lab if l[5]]
    if bad: out.write("  SPECMISMATCH: "+str(bad)+"\n")
    nores=[l for l in lab if not any(o[5]==l[1] for o in obs)]
    if nores: out.write("  SPEC_NO_RESULT: "+str([(l[0],l[1],l[2]) for l in nores])+"\n")
    interesting=[d for d in docs if d[1] not in ('Telephone encounter','Nursing note','Progress note','STI clinic visit','New patient visit')]
    out.write("  DOCS: "+str([(d[0],d[1]) for d in docs])+"\n")
    if tasks: out.write("  REQUESTS: "+str(tasks)+"\n")
    out.write("\n")
out.close()
print('done')
